import{_ as r,o as t,c as o,a3 as a}from"./chunks/framework.By61hD98.js";const p=JSON.parse('{"title":"Bybit SDK error handling","description":"Interpret Bybit API responses, HTTP failures and transport errors.","frontmatter":{"title":"Bybit SDK error handling","description":"Interpret Bybit API responses, HTTP failures and transport errors."},"headers":[],"relativePath":"guides/errors.md","filePath":"guides/errors.md"}'),s={name:"guides/errors.md"};function n(i,e,d,c,l,h){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="error-handling" tabindex="-1">Error handling <a class="header-anchor" href="#error-handling" aria-label="Permalink to &quot;Error handling&quot;">​</a></h1><h2 id="api-errors-in-successful-http-responses" tabindex="-1">API errors in successful HTTP responses <a class="header-anchor" href="#api-errors-in-successful-http-responses" aria-label="Permalink to &quot;API errors in successful HTTP responses&quot;">​</a></h2><p>By default, a Bybit response with a nonzero <code>retCode</code> is returned to the caller. A resolved promise alone does not establish success. Check <code>retCode</code> before reading <code>result</code>, as the Quickstart does.</p><p>You can enable <code>throwExceptions: true</code> in the first constructor argument to reject these responses. This changes control flow; retain a <code>catch</code> handler and do not assume every thrown value is an <code>Error</code> instance.</p><h2 id="http-and-transport-failures" tabindex="-1">HTTP and transport failures <a class="header-anchor" href="#http-and-transport-failures" aria-label="Permalink to &quot;HTTP and transport failures&quot;">​</a></h2><p>HTTP failures reject the request. With the default exception parsing, an HTTP error can contain <code>code</code> (the HTTP status), <code>message</code>, <code>body</code> and <code>headers</code>. Read Bybit&#39;s exchange code from <code>body.retCode</code> in this case. A timeout or connection failure may have a different shape.</p><p><code>parse_exceptions: false</code> retains the original transport error. This is separate from <code>throwExceptions</code>, which controls Bybit response codes.</p><h2 id="log-useful-fields" tabindex="-1">Log useful fields <a class="header-anchor" href="#log-useful-fields" aria-label="Permalink to &quot;Log useful fields&quot;">​</a></h2><p>Log the operation name, market category, symbol, HTTP status and exchange error code. Avoid logging the complete error or <code>requestOptions</code>: the Bybit parser includes client options, which may contain credentials. Keep API keys, signatures and account data out of routine logs.</p><h2 id="decide-what-to-retry" tabindex="-1">Decide what to retry <a class="header-anchor" href="#decide-what-to-retry" aria-label="Permalink to &quot;Decide what to retry&quot;">​</a></h2><p>Fix invalid parameters and permissions before retrying. Use bounded backoff for retryable read failures. A timeout on a state-changing request leaves the outcome uncertain; check the order before submitting another request.</p><p>See <a href="/docs/bybit/guides/production.html">Production usage</a> and the <a href="https://bybit-exchange.github.io/docs/v5/error" target="_blank" rel="noreferrer">Bybit error-code reference</a>.</p>',12)])])}const f=r(s,[["render",n]]);export{p as __pageData,f as default};
